test.use({viewport:{width:1440,height:900},actionTimeout:8000,navigationTimeout:15000});
const errors=new WeakMap<Page,string[]>();
function listen(page:Page){if(errors.has(page))return;const rows:string[]=[];errors.set(page,rows);page.on('pageerror',e=>rows.push(e.message));}
test.beforeEach(async({page})=>listen(page));
test.afterEach(async({context},info)=>{for(const [i,page]of context.pages().entries())if(!page.isClosed()){
 await page.evaluate(()=>{const w=window as any;w.__ta08ReleaseWrite?.();w.__ta08RestorePut?.();w.__ta08Observer?.disconnect();w.__ta08RestoreVisibility?.();});
 await info.attach('ta08-page-errors-'+i,{body:JSON.stringify(errors.get(page)??[]),contentType:'application/json'});expect(errors.get(page)??[]).toEqual([]);
}});
async function attach(info:TestInfo,name:string,data:unknown){await info.attach(name,{body:JSON.stringify(data),contentType:'application/json'});}
async function database(page:Page){return page.evaluate(()=>new Promise<any>((accept,reject)=>{
 const r=indexedDB.open('chenyuan-playable-v1');r.onupgradeneeded=()=>{r.transaction!.abort();reject(new Error('Readonly TA08 observation must not create a database'));};r.onerror=()=>reject(r.error);
 r.onsuccess=()=>{const db=r.result,tx=db.transaction([...db.objectStoreNames],'readonly'),rows:any={};for(const name of db.objectStoreNames){rows[name]=[];const q=tx.objectStore(name).openCursor();q.onsuccess=()=>{if(q.result){rows[name].push({key:q.result.key,value:q.result.value});q.result.continue();}};}tx.oncomplete=()=>{db.close();accept({version:db.version,rows});};tx.onabort=()=>{db.close();reject(tx.error);};};
}));}
function lawfulSource(sourceId:string,realm:C.RealmId='qi',full=false):Game{
 const d=driver('leave','sword');while(C.rank(d.game.core.player.realm)<C.rank(realm))d.realm();if(full)d.meditate();d.go(C.sources[sourceId].location);validateGame(d.game);return structuredClone(d.game) as Game;
}
async function load(page:Page,game:Game,virtual=true){
 listen(page);if(virtual)await useJourneyClock(page);await page.goto('/');await expect(page.getByLabel('导入已有存档',{exact:true})).toBeEnabled();await expect(page.locator('.app-shell')).toHaveAttribute('data-font-scale','1');const raw=await database(page);
 await page.getByLabel('导入已有存档',{exact:true}).setInputFiles({name:'lawful-ta08-source.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(game))});await expect(page.getByTestId('action-execution')).toBeVisible();
 if(virtual){await expect(page.getByTestId('action-countdown')).toHaveText('0.6 秒');await page.clock.runFor(599);expect(await database(page)).toEqual(raw);await page.clock.runFor(1);}await expect(page.getByTestId('save-status')).toHaveText('已保存');
 const actual=await snapshot(page) as Game,expected=structuredClone(game);expected.core.runId=actual.core.runId;expected.core.revision=0;if(expected.core.activeEvent)expected.core.activeEvent.instanceId=actual.core.runId+':'+expected.core.activeEvent.id;expect(actual).toEqual(expected);expect(await activity(page)).toBeNull();return actual;
}
async function sourceView(page:Page,id:string){await page.getByTestId('tab-1').click();await page.getByTestId('explore-mode-source').click();await choose(page,id);}
async function choose(page:Page,id:string){await closeSourceSettings(page);await revealPaged(page,'source-'+id,'source-planner','来源');await inspectSourceLibrary(page,id);await expect(page.getByTestId('source-'+id)).toHaveAttribute('aria-pressed','true');await expect(page.locator('.source-chosen')).toContainText(C.sources[id].name);}
