async function coldNatural(page:Page,id:string,info:TestInfo){
 const object=page.getByTestId('source-physical-object');await expect(object).toBeVisible();await expect(object).toHaveAttribute('data-source',id);await expect(object).toHaveAttribute('data-working','false');
 const art=object.locator('[data-asset-id="source-'+id+'-cold"]');await expect(art).toHaveAttribute('data-art-state','ready');
 const image=await art.locator('img').evaluate(n=>{if(!(n instanceof HTMLImageElement))throw new Error('A loaded natural painting must be its actual image element');const r=n.getBoundingClientRect();return{src:n.getAttribute('src'),width:n.naturalWidth,height:n.naturalHeight,fit:getComputedStyle(n).objectFit,box:{left:r.left,right:r.right,top:r.top,bottom:r.bottom,width:r.width,height:r.height}};});
 expect(image.width).toBe(512);expect(image.height).toBe(512);expect(image.fit).toBe('contain');expect(image.src).toContain('/art/v2/sources/'+id+'-cold-v1.webp');expect(image.box.width).toBeGreaterThan(0);expect(image.box.height).toBeGreaterThan(0);
 await expect(page.getByTestId('source-object-arrange')).toBeVisible();await expect(page.getByTestId('source-commission-object')).toHaveCount(0);await expect(page.getByTestId('source-satchel')).toBeVisible();await attach(info,id+'-actual-cold-image',image);
}

const commissionShapes:Record<string,string>={work:'sweep',core:'escort',jade_task:'survey',work_foundation:'array',lotus_task:'garden',work_golden:'teach',soul_task:'repose',work_nascent:'anchor',dao_task:'rubbing',work_spirit:'province'};
